                  </button>
                  <button onClick={() => goTo('submissions')} style={{ padding: '12px 24px', background: page === 'submissions' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
