                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Title</th>}
                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Description</th>}
                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Syllabus</th>}
                        {page === 'courses' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Enrolled</th>}
                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Action</th>}

                        {(page === 'assignments' || page === 'announcements') && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Title</th>}
                        {page === 'assignments' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Due Date</th>}
                        {page === 'assignments' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Description</th>}
                        {(page === 'assignments' || page === 'announcements') && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Course</th>}
                        {(page === 'assignments' || page === 'announcements') && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Actions</th>}

                        {page === 'submissions' && user.role === 'student' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Assignment</th>}
                        {page === 'submissions' && user.role === 'student' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Your Answer</th>}
                        {page === 'submissions' && user.role === 'student' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Actions</th>}
                        {page === 'submissions' && user.role === 'student' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Grade</th>}

                        {page === 'submissions' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Student</th>}
                        {page === 'submissions' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Assignment</th>}
                        {page === 'submissions' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Answer</th>}
                        {page === 'submissions' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Grade</th>}
                        {page === 'submissions' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Action</th>}

                        {page === 'students' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Name</th>}
                        {page === 'students' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Email</th>}
                        {page === 'students' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Actions</th>}
                      </tr>
                    </thead>
                    <tbody>
                      {data.map(item => (
                        <tr key={item.id} style={{ borderBottom: '1px solid #e2e8f0' }}>
                          <td style={{ padding: '16px', color: '#2d3748' }}>{item.id}</td>

                          {page === 'courses' && <td style={{ padding: '16px' }}>{item.title}</td>}
                          {page === 'courses' && <td style={{ padding: '16px' }}>{item.description}</td>}
                          {page === 'courses' && <td style={{ padding: '16px' }}>{item.syllabus || '—'}</td>}
                          {page === 'courses' && user.role === 'instructor' && <td style={{ padding: '16px' }}>{(item.students || []).length}</td>}
                          {page === 'courses' && (
                            <td style={{ padding: '16px' }}>
                              {user.role === 'instructor' && (
                                <div style={{ display: 'flex', gap: '8px' }}>
                                  <button onClick={() => startEdit(item)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Edit</button>
                                  <button onClick={() => openDeleteConfirm(item.id, 'courses')} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button>
                                </div>
                              )}
                              {user.role === 'student' && (
                                <button
                                  onClick={() => (item.students || []).includes(user.id) ? drop(item.id) : enroll(item.id)}
                                  style={{ padding: '10px 20px', background: (item.students || []).includes(user.id) ? '#e53e3e' : '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}
                                >
                                  {(item.students || []).includes(user.id) ? 'Drop Course' : 'Enroll'}
                                </button>
                              )}
                            </td>
                          )}

                          {(page === 'assignments' || page === 'announcements') && <td style={{ padding: '16px' }}>{item.title}</td>}
                          {page === 'assignments' && <td style={{ padding: '16px' }}>{item.duedate || 'No due date'}</td>}
                          {page === 'assignments' && <td style={{ padding: '16px' }}>{item.description || '—'}</td>}
                          {(page === 'assignments' || page === 'announcements') && <td style={{ padding: '16px' }}>{item.courseid}</td>}
                          {(page === 'assignments' || page === 'announcements') && user.role === 'instructor' && (
                            <td style={{ padding: '16px' }}>
                              <div style={{ display: 'flex', gap: '8px' }}>
                                <button onClick={() => startEdit(item)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Edit</button>
                                <button onClick={() => openDeleteConfirm(item.id, page === 'assignments' ? 'assignments' : 'announcements')} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button>
                              </div>
                            </td>
                          )}

                          {page === 'assignments' && user.role === 'student' && (
                            <td style={{ padding: '16px' }}>
                              <button onClick={() => setSelectedAssignment(item)} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                                Submit Answer
                              </button>
                            </td>
                          )}

                          {page === 'submissions' && user.role === 'student' && <td style={{ padding: '16px' }}>{item.assignmentid}</td>}
                          {page === 'submissions' && user.role === 'student' && (
                            <td style={{ padding: '16px' }}>
                              {item.fileurl ? (
                                <button onClick={() => viewSubmission(item.fileurl, item.id)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
                                  View Answer
                                </button>
                              ) : 'No submission'}
                            </td>
                          )}
                          {page === 'submissions' && user.role === 'student' && item.fileurl && (
                            <td style={{ padding: '16px' }}>
                              <button onClick={() => requestDeleteSubmission(item.id)} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
                                Delete
                              </button>
                            </td>
                          )}
                          {page === 'submissions' && user.role === 'student' && <td style={{ padding: '16px', fontWeight: item.grade !== null ? '600' : 'normal', color: item.grade !== null ? '#48bb78' : '#718096' }}>
                            {item.grade !== null ? `${item.grade}/100` : 'Not graded'}
                          </td>}

                          {page === 'submissions' && user.role === 'instructor' && <td style={{ padding: '16px' }}>Student {item.studentid}</td>}
                          {page === 'submissions' && user.role === 'instructor' && <td style={{ padding: '16px' }}>Assignment {item.assignmentid}</td>}
                          {page === 'submissions' && user.role === 'instructor' && (
                            <td style={{ padding: '16px' }}>
                              {item.fileurl ? (
                                <button onClick={() => viewSubmission(item.fileurl, item.id)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
                                  View Answer
                                </button>
                              ) : 'No submission'}
                            </td>
                          )}
                          {page === 'submissions' && user.role === 'instructor' && <td style={{ padding: '16px', fontWeight: item.grade !== null ? '600' : 'normal', color: item.grade !== null ? '#48bb78' : '#718096' }}>
                            {item.grade !== null ? `${item.grade}/100` : 'Not graded'}
                          </td>}
                          {page === 'submissions' && user.role === 'instructor' && (
                            <td style={{ padding: '16px' }}>
                              {item.grade === null ? (
                                <button onClick={() => gradeSubmission(item)} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                                  Grade
                                </button>
                              ) : (
                                <button onClick={() => gradeSubmission(item)} style={{ padding: '10px 20px', background: '#ed8936', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                                  Regrade
                                </button>
                              )}
                            </td>
                          )}

                          {page === 'students' && <td style={{ padding: '16px' }}>{item.name}</td>}
                          {page === 'students' && <td style={{ padding: '16px' }}>{item.email}</td>}
                          {page === 'students' && (
                            <td style={{ padding: '16px' }}>
                              <div style={{ display: 'flex', gap: '8px' }}>
                                <button onClick={() => startEdit(item)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Edit</button>
                                <button onClick={() => openDeleteConfirm(item.id, 'users')} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button>
                              </div>
                            </td>
