                    Submit Assignment
                  </button>
                  <button onClick={() => { setSelectedAssignment(null); setSubmissionText(''); }} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* View Submission Modal */}
          {showFileModal && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '700px', maxHeight: '90vh', overflow: 'auto', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>{user.role === 'instructor' ? 'Student Answer' : 'Your Answer'}</h3>
                <div style={{ background: '#f8fafc', padding: '24px', borderRadius: '12px', border: '1px solid #e2e8f0', whiteSpace: 'pre-wrap', fontSize: '1.1rem', lineHeight: '1.6' }}>
                  {currentSubmissionText || 'No content submitted.'}
                </div>
                {user.role === 'student' && currentSubmissionId && (
                  <button onClick={() => requestDeleteSubmission(currentSubmissionId)} style={{ marginTop: '20px', padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
                    Delete This Submission
                  </button>
                )}
                <button onClick={() => setShowFileModal(false)} style={{ marginTop: '20px', marginLeft: '10px', padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
                  Close
                </button>
              </div>
            </div>
          )}

          {/* Grade Submission Modal */}
          {showGradeModal && submissionToGrade && user.role === 'instructor' && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '700px', maxHeight: '90vh', overflow: 'auto', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>Grade Submission</h3>
                <p><strong>Student ID:</strong> {submissionToGrade.studentid}</p>
                <p><strong>Assignment ID:</strong> {submissionToGrade.assignmentid}</p>

                <div style={{ background: '#f8fafc', padding: '20px', borderRadius: '12px', margin: '20px 0', border: '1px solid #e2e8f0' }}>
                  <strong>Student Answer:</strong>
                  <div style={{ marginTop: '10px', whiteSpace: 'pre-wrap', fontSize: '1.1rem', lineHeight: '1.6' }}>
                    {submissionToGrade.fileurl || 'No submission'}
                  </div>
                </div>

                <label style={{ display: 'block', margin: '15px 0 5px', fontWeight: '600' }}>Grade (0-100):</label>
                <input
                  type="number"
                  min="0"
                  max="100"
                  value={gradeValue}
                  onChange={(e) => setGradeValue(e.target.value)}
                  style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                />

                <label style={{ display: 'block', margin: '15px 0 5px', fontWeight: '600' }}>Feedback (optional):</label>
                <textarea
                  value={feedbackText}
                  onChange={(e) => setFeedbackText(e.target.value)}
                  rows="4"
                  style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                />

                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                  <button onClick={saveGrade} style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Save Grade
                  </button>
                  <button onClick={() => { setShowGradeModal(false); setGradeValue(''); setFeedbackText(''); setSubmissionToGrade(null); }} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Add/Edit Form Modal */}
          {showForm && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '500px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>{editingItem ? 'Edit' : 'Add'} {page.slice(0, -1)}</h3>
                <form onSubmit={saveItem}>
                  {Object.keys(getEmptyForm(page)).map(key => (
                    <div key={key} style={{ marginBottom: '20px' }}>
                      <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#4a5568' }}>
                        {key.charAt(0).toUpperCase() + key.slice(1)}:
                      </label>
                      {['announcements', 'assignments'].includes(page) && key === 'courseid' ? (
                        <select
                          value={formData[key] || ''}
                          onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                          required
                          style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                        >
                          <option value="">Select course</option>
                          {courses.map(course => (
                            <option key={course.id} value={course.id}>
                              {course.id} - {course.title}
                            </option>
                          ))}
                        </select>
                      ) : (
                        <input
                          type={key === 'duedate' ? 'date' : 'text'}
                          value={formData[key] || ''}
                          onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                          required
                          style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                        />
                      )}
                    </div>
                  ))}
                  <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
                    <button type="submit" style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                      Save
                    </button>
                    <button type="button" onClick={() => setShowForm(false)} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Delete Confirmation */}
          {showConfirmDelete && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ margin: '0 0 20px', color: '#2d3748' }}>Confirm Delete</h3>
                <p style={{ margin: '0 0 30px', color: '#718096' }}>Are you sure you want to delete this permanently?</p>
                <div style={{ display: 'flex', justifyContent: 'center', gap: '15px' }}>
                  <button onClick={confirmDelete} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Yes, Delete
                  </button>
                  <button onClick={() => setShowConfirmDelete(false)} style={{ padding: '12px 28px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}
        </>
      )}

      <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
        <h3 style={{ margin: '0 0 10px' }}>NM Student Portal © 2025</h3>
        <p style={{ margin: 0, opacity: 0.9 }}>Full Role-Based Learning Management System</p>
      </footer>
    </div>
  );
}

export default App;
